using SkillsetsBackend.Application.Auth.Interfaces; using SkillsetsBackend.Application.Common; using SkillsetsBackend.Application.Managers.DTOs; using SkillsetsBackend.Application.Managers.Interfaces; using SkillsetsBackend.Application.Students; using SkillsetsBackend.Domain.Identity; using SkillsetsBackend.Shared.Common;
namespace SkillsetsBackend.Application.Managers.Queries.ListManagers;
public sealed class ListManagersQueryHandler(IManagerQueryService service,IUserDirectory directory){ public async Task<PaginatedList<ManagerListItemDto>> Handle(int page,int pageSize,string? search,int? companyId,bool? active,string? sort,bool descending,string? role,CallerContext caller,CancellationToken ct){if(!caller.IsSuperAdmin&&caller.Role!=Roles.Manager&&caller.Role!=Roles.CompanyAdmin)throw new UnauthorizedAccessException("Only SuperAdmin, company managers, and company admins can list managers."); if(role=="CompanyAdmin"&&!caller.IsSuperAdmin&&caller.Role!=Roles.CompanyAdmin)throw new UnauthorizedAccessException("Only SuperAdmin and company admins can list company admins."); IReadOnlyCollection<int>? allowed=null;if(caller.IsSuperAdmin)allowed=companyId is null?null:[companyId.Value];else{var managed=await StudentAuthorization.GetManagedCompanyIdsAsync(caller,directory,ct);if(companyId is not null&&!managed.Contains(companyId.Value))throw new UnauthorizedAccessException("You do not have access to that company.");allowed=companyId is null?managed:[companyId.Value];}return await service.ListAsync(new(Math.Max(1,page),pageSize<=0?50:Math.Min(200,pageSize),search,active,sort,descending,allowed,role),ct);}}
